import{S as t,o as d,c as a,a9 as c,B as i}from"./chunks/framework.IJ8axLs_.js";const n="/agentsrc/images/deepseek/05-seam-triple.svg",r="/agentsrc/images/deepseek/05-execution-world.svg",l="/agentsrc/images/deepseek/05-tool-pipeline.svg",b=JSON.parse('{"title":"capability 缝与执行世界：换一个实现，动整套产品","description":"","frontmatter":{"title":"capability 缝与执行世界：换一个实现，动整套产品"},"headers":[],"relativePath":"deepseek/05-capability-seams.md","filePath":"deepseek/05-capability-seams.md","lastUpdated":1790217011000}'),p={name:"deepseek/05-capability-seams.md"},m=Object.assign(p,{setup(h){const o=[{question:"按 `dsh` 的定义，一个能力最少要设计哪三种角色？",options:["接口、实现、消费方","接口、实现、配置","工具、沙箱、审批","接口、事件、日志"],correct:0,explanation:"capability 缝 = Service Definition + Provider + Consumer，缺一不算 seam。B 用配置顶替消费方，C 是具体能力名，D 是机制要素不是角色划分。"},{question:"接口包（Service Definition）为什么不能 import 任何实现包？",options:["为了减少包的安装体积","因为实现包不许被别人引用","换实现时消费方也得跟着改","为了让编译速度更快"],correct:2,explanation:"接口一旦绑死实现，Consumer 就跟着焊死；接口独立成包，Provider 随便换、消费方与整棵树不动。A/B/D 都不是这条依赖规则的理由。"},{question:"单调守卫（ToolGuard）的返回类型刻意没有 allow 分支，目的是？",options:["让守卫更短更容易写","后续监听者无法把拒绝翻回放行","减少一次类型判断的开销","让审批流程接管允许权"],correct:1,explanation:"返回 undefined 维持原判、返回理由只会收紧：裁决只紧不松，防止监听者之间互相翻案。A/C 与设计意图无关，D 说的是 approval 的位置而非守卫。"},{question:"一次工具调用带 `danger-full-access` 模式，实际会发生什么？",options:["沙箱以最宽规则包住进程","调用被拒绝并要求审批","沙箱后端切换到全量模式","绕过沙箱，直接执行原命令"],correct:3,explanation:'danger-full-access 是旁路：消费方直接 spawn 原 argv，根本不调 ctx.sandbox。A/C 把旁路误读成最宽围栏，B 混淆了"请求放宽一档"的人工审批路径。'},{question:'"换一个 provider 会带着 bash、PTY、LSP 整套搬家"的根本原因是？',options:["这些工具写在同一个包里","配置文件强制绑定它们的行","它们共享同一个执行世界","它们的接口签名完全相同"],correct:2,explanation:"fs 与 subprocess 共享一个执行世界，bash/PTY/LSP 都经 ctx.subprocess 这条缝去 spawn；把世界指向远程，ssh 三件套（fs-ssh/subprocess-ssh/sandbox-ssh）一起换，所有消费者自动迁移。A/C/D 都不是机制本身。"}];return(u,e)=>{const s=t("Quiz");return d(),a("div",null,[e[0]||(e[0]=c('<h1 id="capability-缝与执行世界-换一个实现-动整套产品" tabindex="-1">capability 缝与执行世界：换一个实现，动整套产品 <a class="header-anchor" href="#capability-缝与执行世界-换一个实现-动整套产品" aria-label="Permalink to &quot;capability 缝与执行世界：换一个实现，动整套产品&quot;">​</a></h1><p>上一篇结尾留了一个问题：为什么换一个 provider 能牵一发动全身？这一篇正面拆它。<code>dsh</code> 把每个能力——执行 bash、读写文件、起子进程、沙箱隔离——都做成一条 <strong>capability 缝</strong>，缝的机制一句话能说完，但它解释的事横跨整个仓库。读完你会带着三个问题的答案离开：</p><ul><li>一个能力为什么要拆成三个角色、三个包，接口单独成包图什么？</li><li>为什么说 fs 与 subprocess 共享一个&quot;执行世界&quot;，换一个 provider 会带着 bash、PTY、LSP 整套搬家？</li><li>一次工具调用从模型发起到落盘要过多少道裁决，为什么参数不可改而结果可改？</li></ul><p>压缩那条缝上一篇已经见过，这篇把它当成熟人引用；工具执行管线的完整机制在这里讲透。</p><h2 id="一、三件套-一个能力的最小完整拼图" tabindex="-1">一、三件套：一个能力的最小完整拼图 <a class="header-anchor" href="#一、三件套-一个能力的最小完整拼图" aria-label="Permalink to &quot;一、三件套：一个能力的最小完整拼图&quot;">​</a></h2><p>先看定义，架构文档一句话说完：</p><blockquote><p>A <strong>seam</strong> is a swappable capability with three roles: a <strong>Service Definition</strong> declaring the interface, a <strong>Service Provider</strong> implementing it, and a <strong>Consumer</strong> using it, commonly a model-facing tool. A package may combine roles, but one role alone is not a seam; adding a capability means designing all three.</p></blockquote><p>三个角色对应三种演化方向。<strong>Service Definition</strong> 声明接口：这个能力能做什么、返回什么、暴露哪些事件，它不依赖任何实现。<strong>Service Provider</strong> 给出具体实现，同一时刻同层只有一个挂载。<strong>Consumer</strong> 消费能力，通常是一个模型可见的工具。缺任何一个角色都不构成缝——只有一个接口包没有实现，等于纸上谈兵；工具直接 import 实现包，换实现就得改工具。</p><p><img src="'+n+`" alt="capability 缝的三件套"></p><p>接口为什么必须独立成包？因为 Consumer 只对着接口编程：<code>dsh-tool-bash</code> 调的是 <code>ctx.shell.run(...)</code> 这个接口方法，<code>ctx.shell</code> 下面挂的是本地执行器还是沙箱执行器，它不知道也不需要知道。实现换掉，Consumer 与整棵树上的其他插件都不动。反过来，接口包里只要 import 了一个实现，这条缝就焊死了。</p><p><code>dsh</code> 的依赖规则在第一篇出现过：扩展插件只依赖 Service Definition，绝不依赖具体 provider。角色完整性还是机器可查的——<code>docs/capability-seams.md</code> 这张生成的图谱把全仓每个 <code>ctx.*</code> 服务按三种角色归类，谁少做了一个角色，组合时 fail loud。</p><h2 id="二、bash-缝-接口、实现与能力事实" tabindex="-1">二、bash 缝：接口、实现与能力事实 <a class="header-anchor" href="#二、bash-缝-接口、实现与能力事实" aria-label="Permalink to &quot;二、bash 缝：接口、实现与能力事实&quot;">​</a></h2><p>用最典型的 bash 缝把三件套落地。<code>dsh-shell</code> 定义 <code>ShellExecutor</code>：前台 <code>run</code> 一条命令读有界输出、<code>start</code> 一个后台进程轮询结果，外加一个 <code>resolve()</code> 和一个 <code>sandboxMode</code> 能力事实。Provider 是四个执行器——<code>bash-local</code>（POSIX 本地子进程）、<code>bash-sandbox</code>（每条命令过沙箱）、<code>pwsh-local</code> / <code>pwsh-sandbox</code>（Windows 的 PowerShell 版）；Consumer 是 <code>tool-bash</code>、<code>tool-pwsh</code> 这组模型工具。</p><p>两条设计值得放大。</p><p><strong>其一，request 与 spec 的分离。</strong> 模型和插件传进来的 <code>ShellExecRequest</code> 里，<code>workdir</code>、<code>timeoutMs</code>、<code>stdoutMaxBytes</code> 全是可选的；执行器真正执行的 <code>ShellExecSpec</code> 里这些字段全是必填。中间隔着一个显式的 <code>ctx.shell.resolve(request)</code>：实现自己的配置与请求策略在这里填默认值、封上限。</p><p>仓库的规则原文是 &quot;explicit &gt; implicit at package boundaries&quot;：默认值是 owning 实现里一个显式的解析步骤，绝不藏在 <code>run()</code> 内部的 <code>??</code> 兜底里。<code>dsh-shell</code> 的这个拆法被仓库指定为模板，其他缝照此办理。</p><p><strong>其二，sandboxMode 作为能力事实。</strong> 沙箱型执行器在 <code>ShellExecutor.sandboxMode</code> 上暴露自己的模式回退值，工具层读它：有沙箱执行器在位，<code>bash</code> 工具就多一个&quot;请求沙箱&quot;的参数；纯本地执行器在位，这个参数自动消失。Consumer 按照实现暴露的能力事实<strong>自适应</strong>自己的 schema——不需要工具知道 bwrap 还是 Landlock。这正是三件套里&quot;三个角色各自演化&quot;的意思：Provider 换了，Consumer 的模型面跟着长出或收起一个开关。</p><p>同层互斥同样硬：一个组合只挂一个执行器，挂两个会在加载期因为重复的服务注册 fail loud。&quot;换 provider&quot;因此是原子操作，不存在半套本地半套远程的中间态。</p><h2 id="三、sandbox-缝-同世界的文件效果约束" tabindex="-1">三、sandbox 缝：同世界的文件效果约束 <a class="header-anchor" href="#三、sandbox-缝-同世界的文件效果约束" aria-label="Permalink to &quot;三、sandbox 缝：同世界的文件效果约束&quot;">​</a></h2><p>沙箱缝的接口极小：<code>ctx.sandbox.confine(argv, policy, signal)</code> 把一条同世界子进程 argv 包进文件效果策略。策略词汇只有三档：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// docs/subsystems/sandbox.md（节选）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SandboxMode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;read-only&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;workspace-write&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;danger-full-access&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SandboxEnforcement</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;full&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;partial&#39;</span></span></code></pre></div><p>三个词汇的边界都画得很死。<code>SandboxMode</code> 只管文件效果：<code>read-only</code> 拒绝写入（POSIX 后端额外放行 shell 需要的 <code>/dev/null</code>），<code>workspace-write</code> 允许工作区根与后端承诺的临时区，<code>danger-full-access</code> 彻底旁路——走这个模式的调用根本不会调 <code>ctx.sandbox</code>，直接 spawn 原 argv。网络与进程可见性不在这套词汇里。</p><p><code>SandboxEnforcement</code> 是后端报告的事实而非承诺：<code>full</code> 表示后端管住模式承诺的全部文件效果，<code>partial</code> 表示旧内核 ABI 或平台边界只覆盖一部分——要求绝对保证的消费方必须自己拒绝或明示这个差异。</p><p>失败方向同样是关死的。请求的模式无法强制时，调用以 <code>SANDBOX_UNAVAILABLE</code> 失败，绝不无沙箱裸跑——&quot;Silent unconfined passthrough is never legal&quot; 写进了服务契约。被拒之后，模型可以为这次调用请求放宽一档，交人工审批。</p><p>后端按平台各就各位：Linux 上 bwrap 与 Landlock，macOS 上 Seatbelt，Windows 上 ACL 受限令牌。这些后端全部是<strong>同世界</strong>的——沙箱进程仍与宿主共享内核与文件系统。README 把边界说得很清楚：需要隔离整个环境时，答案不是更强的沙箱，而是容器、微 VM 或远程执行器。最后这半句是下一节的入口。</p><h2 id="四、执行世界-换-provider-整套搬家" tabindex="-1">四、执行世界：换 provider = 整套搬家 <a class="header-anchor" href="#四、执行世界-换-provider-整套搬家" aria-label="Permalink to &quot;四、执行世界：换 provider = 整套搬家&quot;">​</a></h2><p>现在回答标题里的&quot;动整套产品&quot;。架构文档的关键句：</p><blockquote><p>Seams are why one provider swap changes the whole product. Filesystem and subprocess providers share one execution world, so pointing them at a remote sandbox moves Bash, PTY, and LSP with them, with no provider forks.</p></blockquote><p>fs 缝与 subprocess 缝共享同一个<strong>执行世界</strong>：一个进程能打开哪个路径，取决于它所在世界的文件系统；一条命令在哪里执行，取决于那个世界的子进程设施。这两件事在本地实现里是一体的——<code>fs-local</code> 读真实文件，<code>subprocess-local</code> 起真实进程，共享宿主这个&quot;世界&quot;。</p><p>所以把执行世界整体指向远程时，动的不是某一个工具。看 ssh 组的装配：<code>fs-ssh</code> 注册 <code>ctx.fs</code>（远程文件身份、读取、原子变更守卫）、<code>subprocess-ssh</code> 注册 <code>ctx.subprocess</code>（可执行查找、进程、控制流与终端）、<code>sandbox-ssh</code> 注册 <code>ctx.sandbox</code>（远程文件效果约束）——三件套一起换，挂在 <code>ctx.shell</code> 上的 bash、PTY，还有靠 <code>ctx.subprocess</code> spawn 的 LSP，全部跟着迁到远程，没有任何一条 provider 分叉。</p><p>bash、PTY、LSP、各子 agent 后端都通过 <code>ctx.subprocess</code> 这个单一缝去 spawn，这正是&quot;牵一发动全身&quot;的正面写法：一换全换、干干净净。</p><p>fs 组内部的分层也体现了缝的纵深：<code>fs</code> 是接口（执行世界路径、有界文本 IO、带版本守卫的原子变更），<code>fs-local</code> / <code>fs-sandbox</code> 是两个 provider（后者按每次调用的沙箱模式给写操作上栅栏、读直接放行），<code>fs-observation-policy</code> 是挂在 <code>fs/*</code> 事件上的策略（编辑前必须读过、记录观察到的是否存在），<code>tool-fs</code> / <code>tool-fs-search</code> 是模型面的读写与检索工具。五层各管一段，替换 <code>fs-local</code> 时策略与工具两层原地不动。</p><p><img src="`+r+'" alt="本地与 SSH 两个执行世界的整套迁移"></p><h2 id="五、工具裁决链-consumer-的自由与约束" tabindex="-1">五、工具裁决链：Consumer 的自由与约束 <a class="header-anchor" href="#五、工具裁决链-consumer-的自由与约束" aria-label="Permalink to &quot;五、工具裁决链：Consumer 的自由与约束&quot;">​</a></h2><p>工具是缝最常见的 Consumer，也是裁决链最重的一层。<code>ctx.tools</code> 注册表里一个 <code>ToolDefinition</code> = 模型可见的 schema + <strong>强制的 canonical output 声明</strong> + <code>execute</code> 函数 + 调度元数据 + 可选的展示回调。注册表给模型的投影走显式白名单：<code>output</code>、<code>execute</code>、<code>finalizeContent</code>、<code>timeoutMs</code>、<code>isConcurrencySafe</code>、<code>presentCall</code>、<code>presentResult</code> 这些字段<strong>永不进模型请求</strong>——模型看到的只有 <code>name</code>、<code>description</code>、<code>parameters</code>。</p><p>自家插件用 <code>defineTool()</code> 拿类型安全：参数先验证再进 body，返回值按 <code>output.schema</code> 推断。</p><p>一次调用从模型发出到落盘，完整过这条链：</p><ol><li><strong><code>tool/call</code> 先落日志</strong>——调用还没执行，事实已经记录；</li><li><strong><code>tools/pre-execute</code> 瀑布</strong>（allow / deny / ask / cancel）：hooks、权限、沙箱策略都在这层挂；</li><li><strong><code>ctx.approval</code> 一次性审批</strong>：<code>ask</code> 在这里等人工裁决，批一次（allowed-once）放行；审批服务缺席或无法应答，一律按 deny 收场；</li><li><strong>单调守卫</strong>：注册进注册表的最终策略，返回类型<strong>刻意没有 allow 分支</strong>——<code>undefined</code> 维持瀑布原判，返回理由只会收紧；</li><li><strong><code>tools/execute</code> 瀑布</strong>（around-dispatch）：超时、重试、指标这类包装逻辑挂在这里，且只有这一层允许替换取消信号；</li><li><strong>工具 body</strong> 执行，写操作再过 <code>fs/write-intent</code> 这类能力自己的闸；</li><li><strong><code>projectContent</code></strong>：定义自带的执行内容准备，把执行中产出的文本与图片装进结果，赶在 post-execute 之前；</li><li><strong><code>tools/post-execute</code> 瀑布</strong>：接受、block、替换结果、附加上下文；</li><li><strong><code>finalizeContent</code></strong>：工具自己的最后一道 content-only 修正，随后 <code>tools/result</code> 以冻结的最终事实通知观察者。</li></ol><p><img src="'+l+'" alt="工具调用的裁决链"></p><p>单调守卫的设计值得单独看，<code>tools.md</code> 的原话：</p><blockquote><p>Its return type deliberately has no allow result: <code>undefined</code> preserves the waterfall decision, while a returned reason can only reduce permission, so a later listener cannot undo it.</p></blockquote><p>裁决在这条链上是<strong>只紧不松</strong>的：pre-execute 的 allow 只代表&quot;这一层放行&quot;，后面的守卫随时可以否掉；而任何一层给出的 deny，后面的监听者都翻不了案。审批缺席即拒绝、守卫无 allow 分支、静默无沙箱裸跑不合法——三件事是同一个失败哲学在三个位置的样子。</p><p>链的两端自由度刻意不对称。<strong>进闸（参数）不可改</strong>：pre-execute 不允许改写调用参数，因为参数已经 logged 且展示过，改了会让历史、审计、UI、执行彼此脱钩；<strong>出闸（结果）可改</strong>：post-execute 可以替换 content 或 value——这是策略层对结果的正当修饰，且整条链的每个异常最终都规范成带 <code>isError</code> 的正常结果。保真进、灵活出，历史一致性与策略空间各得其所。</p><h2 id="六、与三栏对比" tabindex="-1">六、与三栏对比 <a class="header-anchor" href="#六、与三栏对比" aria-label="Permalink to &quot;六、与三栏对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>OpenCode / Codex / Claude Code</th><th>DeepSeek Harness</th></tr></thead><tbody><tr><td>工具与沙箱</td><td>产品内建，硬编码在循环周围</td><td>缝：三件套各占一个包</td></tr><tr><td>换沙箱/执行后端</td><td>改代码</td><td>换一个 Provider</td></tr><tr><td>bash+文件+LSP 整体迁移</td><td>满仓库改</td><td>换共享执行世界的一组 provider</td></tr><tr><td>工具权限</td><td>产品的权限模块</td><td>pre-execute/审批/单调守卫，全挂插件</td></tr></tbody></table><p>三个终端 Agent 把工具和沙箱当作产品中心的能力写进代码；<code>dsh</code> 把它们做成可插换的缝，再把共享执行世界的几条缝绑成一组，让&quot;换环境&quot;从满仓库打补丁变成一次整套迁移。加上工具裁决链把&quot;给模型一个工具&quot;从一次性决定拆成每一步都可裁决的管线，这一篇和前四篇拼起来正好是 <code>dsh</code> 的能力面全景。</p><p>最后一篇看它把&quot;可换&quot;推到的三个极致：agent 改自己、翻译别家 hooks、跨产品委托。</p><h2 id="源码索引" tabindex="-1">源码索引 <a class="header-anchor" href="#源码索引" aria-label="Permalink to &quot;源码索引&quot;">​</a></h2><ul><li><code>docs/architecture.md</code> — Capability seams 定义与执行世界</li><li><code>packages/shell/README.md</code> — bash 缝的包族与互斥装配</li><li><code>docs/subsystems/shell.md</code> — request/spec 分离、sandboxMode 能力事实</li><li><code>packages/sandbox/sandbox/README.md</code> + <code>docs/subsystems/sandbox.md</code> — 沙箱模式、enforcement、fail-closed</li><li><code>packages/fs/README.md</code> — fs 缝五层包族</li><li><code>packages/ssh/README.md</code> — 远程执行世界三件套</li><li><code>docs/subsystems/tools.md</code> — 注册表契约、单调守卫、执行管线</li><li><code>docs/tool-execution-pipeline.md</code> — 裁决链全图</li><li><code>docs/capability-seams.md</code> — 机器生成的角色图谱</li></ul><h2 id="章节小测" tabindex="-1">章节小测 <a class="header-anchor" href="#章节小测" aria-label="Permalink to &quot;章节小测&quot;">​</a></h2>',50)),i(s,{questions:o})])}}});export{b as __pageData,m as default};
